"""Build verified follow-up deltas AFTER both source packages have been published.

Do not run during benchmarks. This reads the old/new package receipts, manifests,
and full checkpoint patches, creates only temporary Git indexes/objects, and
publishes a NEW output directory without replacing anything. No source archive
is extracted, no real index is staged, and no Java/build/test/network process runs.
The existing source/evidence packager remains responsible for archive readback.

The complete delta includes every selected source/document change. A second,
smaller code-only patch contains the LMDB source changes, with its own exact-tree
verification. The new package's full checkpoint patch is not rewritten.
"""

from __future__ import annotations

import argparse
import ctypes
import errno
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import shutil
import stat
import subprocess
import sys
import tempfile


BASE_COMMIT = "15fe7d5011d27d31d76436238363ee3f34b3ba50"
PRIOR_TREE = "b747b9b5297ecf5ef9b745dce108939b10d62788"
PRIOR_SUMMARY_SHA256 = "abce69cff52bab0c04dddff9540e82c4f7c54fbbaff582fdfe78f0cd11c44ac2"
PRIOR_PATCH_SHA256 = "b890723c382c943ce10748f143d83e5caac539fab1b774551354a8f03870de93"
CODE_ROOT = "core/sail/lmdb/src/"
# The frame-directory guard did not meet the prospective adoption rule. The only
# actual core-source change in this turn is the nine new coordinate characterizations.
EXPECTED_CODE_PATHS = {
    CODE_ROOT + "test/java/org/eclipse/rdf4j/sail/lmdb/evaluation/codegen/KernelResultCoordinatesTest.java",
}



def require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def json_bytes(value: object) -> bytes:
    return (json.dumps(value, indent=2, sort_keys=True) + "\n").encode("utf-8")


def signature(path: Path) -> tuple[int, ...]:
    info = path.lstat()
    return (info.st_dev, info.st_ino, info.st_mode, info.st_size, info.st_mtime_ns, info.st_ctime_ns)


def read_stable(path: Path, tracked_inputs: dict[Path, tuple[int, ...]]) -> bytes:
    before = signature(path)
    require(stat.S_ISREG(before[2]), f"Expected a regular input file: {path}")
    data = path.read_bytes()
    require(signature(path) == before and len(data) == before[3], f"Input changed while reading: {path}")
    tracked_inputs[path] = before
    return data


def file_hash(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def portable_path(value: str) -> str:
    path = PurePosixPath(value)
    require(value and not path.is_absolute() and path.as_posix() == value
            and all(part not in ("", ".", "..") for part in path.parts)
            and "\\" not in value and "\0" not in value, f"Unsafe package path: {value!r}")
    return value


def load_receipt(directory: Path, inputs: dict[Path, tuple[int, ...]], prior: bool) -> dict:
    sums = {}
    for line in read_stable(directory / "SHA256SUMS", inputs).decode("ascii").splitlines():
        digest, separator, name = line.partition("  ")
        require(separator and len(digest) == 64 and all(c in "0123456789abcdef" for c in digest),
                f"Invalid checksum line in {directory}")
        require(name == Path(name).name and name not in sums, f"Unsafe/duplicate checksum member: {name}")
        sums[name] = digest
    summary_bytes = read_stable(directory / "package-summary.json", inputs)
    summary_hash = hashlib.sha256(summary_bytes).hexdigest()
    require(sums.get("package-summary.json") == summary_hash, "Package summary checksum differs")
    summary = json.loads(summary_bytes)
    require(summary["schema"] == 1 and summary["base_commit"] == BASE_COMMIT,
            "Both source packages must use the exact original checkpoint")
    for field in ("all_external_submodule_sources_included", "patch_apply_tree_equality",
                  "source_archive_verified", "evidence_archive_verified", "real_indexes_unchanged",
                  "inputs_stable_through_verification"):
        require(summary[field] is True, f"Incomplete source-package receipt: {directory}: {field}")
    files = {}
    for name in ("rdf4j-full.patch", "source-manifest.json"):
        data = read_stable(directory / name, inputs)
        digest = hashlib.sha256(data).hexdigest()
        require(summary["artifacts"][name] == {"bytes": len(data), "sha256": digest}
                and sums.get(name) == digest, f"Package artifact differs from its receipt: {name}")
        files[name] = data
    manifest = json.loads(files["source-manifest.json"])
    require(manifest["base_commit"] == BASE_COMMIT
            and manifest["snapshot_tree"] == summary["snapshot_tree"]
            and manifest["all_external_submodule_sources_included"] is True,
            "Source manifest identity differs from package summary")
    if prior:
        require(summary_hash == PRIOR_SUMMARY_SHA256 and summary["snapshot_tree"] == PRIOR_TREE
                and hashlib.sha256(files["rdf4j-full.patch"]).hexdigest() == PRIOR_PATCH_SHA256,
                "The prior delivery does not match the preserved original receipt")
    return {"directory": str(directory), "summary": summary, "summarySha256": summary_hash,
            "manifest": manifest, "patch": files["rdf4j-full.patch"]}


def git_environment() -> dict[str, str]:
    environment = os.environ.copy()
    for key in ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY",
                "GIT_ALTERNATE_OBJECT_DIRECTORIES", "GIT_COMMON_DIR"):
        environment.pop(key, None)
    environment.update({"GIT_OPTIONAL_LOCKS": "0", "GIT_TERMINAL_PROMPT": "0", "GIT_PAGER": "cat",
                        "GIT_NO_LAZY_FETCH": "1"})
    return environment


def git(repo: Path, arguments: list[str], environment: dict[str, str], data: bytes | None = None) -> bytes:
    result = subprocess.run(
        ["git", "--no-pager", "-c", "core.splitIndex=false", "-c", "index.sparse=false",
         "-c", "core.fsmonitor=false", "-c", "core.untrackedCache=false", "-C", str(repo), *arguments],
        input=data, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=environment, check=False,
    )
    require(result.returncode == 0,
            f"Git {' '.join(arguments[:3])} failed: {result.stderr.decode('utf-8', 'replace').strip()}")
    return result.stdout


def tree_entries(repo: Path, tree: str, environment: dict[str, str]) -> dict[str, tuple[str, str]]:
    result = {}
    for entry in git(repo, ["ls-tree", "-r", "-z", tree], environment).split(b"\0"):
        if entry:
            header, raw_path = entry.split(b"\t", 1)
            mode, _kind, oid = header.decode("ascii").split()
            result[portable_path(os.fsdecode(raw_path))] = (mode, oid)
    return result


def manifest_tree_entries(manifest: dict) -> dict[str, tuple[str, str]]:
    submodules = [portable_path(item["path"]) for item in manifest["submodules"]]
    selected = {}
    for entry in manifest["entries"]:
        path = portable_path(entry["path"])
        if any(path.startswith(submodule + "/") for submodule in submodules):
            continue
        require(path not in selected, f"Duplicate source-manifest entry: {path}")
        selected[path] = (entry["mode"], entry["git_oid"])
    return selected


def publish_no_replace(source: Path, destination: Path) -> None:
    require(sys.platform.startswith("linux"), "Atomic publication requires Linux renameat2")
    libc = ctypes.CDLL(None, use_errno=True)
    rename = getattr(libc, "renameat2", None)
    require(rename is not None, "renameat2 unavailable; output remains unpublished")
    rename.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint]
    rename.restype = ctypes.c_int
    if rename(-100, os.fsencode(source), -100, os.fsencode(destination), 1):
        error = ctypes.get_errno()
        if error in (errno.EEXIST, errno.ENOTEMPTY):
            raise FileExistsError(f"Refusing to replace output: {destination}")
        raise OSError(error, os.strerror(error), str(destination))


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", type=Path, default=Path(__file__).resolve().parents[3])
    parser.add_argument("--prior-delivery", type=Path, required=True)
    parser.add_argument("--new-delivery", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True, help="New delta-delivery directory")
    parser.add_argument("--allow-code-path", action="append", default=[],
                        help="Explicit additional LMDB source change permitted in this follow-up")
    args = parser.parse_args()
    repo = args.repo.resolve(strict=True)
    prior_directory = args.prior_delivery.resolve(strict=True)
    new_directory = args.new_delivery.resolve(strict=True)
    output = args.output.parent.resolve(strict=True) / args.output.name
    require(prior_directory != new_directory and not os.path.lexists(output),
            "Distinct source deliveries and an unused output directory are required")
    require(not output.is_relative_to(prior_directory) and not output.is_relative_to(new_directory),
            "Delta publication must not modify either source delivery")
    allowed_code = EXPECTED_CODE_PATHS | {portable_path(value) for value in args.allow_code_path}
    inputs = {}
    old = load_receipt(prior_directory, inputs, True)
    new = load_receipt(new_directory, inputs, False)
    require(old["manifest"]["submodules"] == new["manifest"]["submodules"],
            "A changed external dependency requires a separately designed dependency delta")
    def external_entries(manifest):
        paths = [item["path"] + "/" for item in manifest["submodules"]]
        return [entry for entry in manifest["entries"] if any(entry["path"].startswith(path) for path in paths)]
    require(external_entries(old["manifest"]) == external_entries(new["manifest"]),
            "Vendored external source differs despite an unchanged gitlink")
    environment = git_environment()
    require(Path(git(repo, ["rev-parse", "--show-toplevel"], environment).decode().strip()).resolve() == repo,
            "Repository path is not the Git worktree root")
    head_before = git(repo, ["rev-parse", "--verify", "HEAD"], environment)
    require(git(repo, ["rev-parse", "--verify", BASE_COMMIT + "^{commit}"], environment).decode().strip()
            == BASE_COMMIT, "Original checkpoint object is unavailable")
    def git_path(name):
        value = Path(git(repo, ["rev-parse", "--git-path", name], environment).decode().strip())
        return (value if value.is_absolute() else repo / value).resolve()
    real_index = git_path("index")
    index_before = (real_index.exists(), file_hash(real_index) if real_index.exists() else None)
    original_objects = git_path("objects")
    staging = Path(tempfile.mkdtemp(prefix=".next-experiments-delta-", dir=output.parent))
    published = False
    try:
        with tempfile.TemporaryDirectory(prefix="rdf4j-next-experiments-delta-") as temporary_name:
            temporary = Path(temporary_name)
            objects = temporary / "objects"
            objects.mkdir()
            def isolated(name):
                result = environment.copy()
                result.update({"GIT_INDEX_FILE": str(temporary / (name + ".index")),
                               "GIT_OBJECT_DIRECTORY": str(objects),
                               "GIT_ALTERNATE_OBJECT_DIRECTORIES": str(original_objects)})
                return result
            baseline = tree_entries(repo, BASE_COMMIT, environment)
            restored = []
            for label, receipt in (("prior", old), ("new", new)):
                isolated_env = isolated(label)
                git(repo, ["read-tree", BASE_COMMIT], isolated_env)
                if receipt["patch"]:
                    git(repo, ["apply", "--cached", "--binary", "--whitespace=nowarn", "-"],
                        isolated_env, receipt["patch"])
                actual = git(repo, ["write-tree"], isolated_env).decode().strip()
                require(actual == receipt["summary"]["snapshot_tree"],
                        f"Reconstructed {label} tree differs from its published receipt")
                expected = manifest_tree_entries(receipt["manifest"])
                for path in receipt["manifest"]["excluded_base_paths_left_unchanged_in_patch"]:
                    require(path in baseline, f"Excluded base path is absent: {path}")
                    expected[path] = baseline[path]
                actual_entries = tree_entries(repo, actual, isolated_env)
                require(actual_entries == expected, f"{label} tree differs from its source manifest")
                restored.append((actual, actual_entries))
            (old_tree, old_entries), (new_tree, new_entries) = restored
            changed = sorted(path for path in old_entries.keys() | new_entries.keys()
                             if old_entries.get(path) != new_entries.get(path))
            code_changed = [path for path in changed if path.startswith(CODE_ROOT)]
            require(code_changed and set(code_changed) <= allowed_code,
                    "Unexpected or missing LMDB source delta: " + repr(code_changed))
            diff_arguments = ["diff", "--binary", "--full-index", "--no-color", "--no-ext-diff",
                              "--no-textconv", "--no-renames", "--src-prefix=a/", "--dst-prefix=b/",
                              old_tree, new_tree, "--"]
            full_delta = git(repo, diff_arguments, isolated("diff"))
            code_delta = git(repo, diff_arguments + [CODE_ROOT.rstrip("/")], isolated("diff"))
            require(full_delta and code_delta, "Follow-up delta unexpectedly empty")
            (staging / "rdf4j-from-prior-delivery.patch").write_bytes(full_delta)
            (staging / "rdf4j-next-experiments-code.patch").write_bytes(code_delta)
            results = {}
            for name, patch, expected_entries in (
                ("complete", full_delta, new_entries),
                ("codeOnly", code_delta, {**{p:v for p,v in old_entries.items() if not p.startswith(CODE_ROOT)},
                                         **{p:v for p,v in new_entries.items() if p.startswith(CODE_ROOT)}}),
            ):
                replay = isolated(name)
                git(repo, ["read-tree", old_tree], replay)
                git(repo, ["apply", "--cached", "--binary", "--whitespace=nowarn", "-"], replay, patch)
                result_tree = git(repo, ["write-tree"], replay).decode().strip()
                require(tree_entries(repo, result_tree, replay) == expected_entries,
                        f"{name} delta replay did not produce its exact expected tree")
                if name == "complete":
                    require(result_tree == new_tree, "Complete delta does not equal the new source snapshot")
                git(repo, ["apply", "--cached", "--binary", "--reverse", "--whitespace=nowarn", "-"], replay, patch)
                require(git(repo, ["write-tree"], replay).decode().strip() == old_tree,
                        f"{name} delta reverse application did not restore the prior snapshot")
                results[name] = {"forwardVerified": True, "reverseVerified": True, "resultTree": result_tree}
            require((real_index.exists(), file_hash(real_index) if real_index.exists() else None) == index_before,
                    "Real repository index changed during delta verification")
            require(git(repo, ["rev-parse", "--verify", "HEAD"], environment) == head_before,
                    "Repository HEAD changed during delta verification")
            for path, before in inputs.items():
                require(signature(path) == before, f"A package input changed during verification: {path}")
            verification = {"schema": 1, "baseCommit": BASE_COMMIT, "priorTree": old_tree, "newTree": new_tree,
                            "priorSummarySha256": old["summarySha256"], "newSummarySha256": new["summarySha256"],
                            "realIndexUnchanged": True, "headUnchanged": True, "privateObjectsAndIndexesOnly": True,
                            "externalSourceUnchanged": True, "archiveBytesReverifiedByThisHelper": False,
                            "changedPaths": changed, "codeChangedPaths": code_changed, "patches": results,
                            "artifacts": {name: {"bytes": (staging/name).stat().st_size,
                                                 "sha256": file_hash(staging/name)} for name in
                                          ("rdf4j-from-prior-delivery.patch", "rdf4j-next-experiments-code.patch")}}
            (staging / "delta-verification.json").write_bytes(json_bytes(verification))
            (staging / "README.md").write_text(
                "# Verified next-experiment deltas\n\n"
                "rdf4j-from-prior-delivery.patch transforms the complete previous selected source tree into the new one.\n"
                "rdf4j-next-experiments-code.patch contains only the LMDB source/test changes; documentation and delivery helpers are excluded.\n"
                "Both patches were applied and reversed in private Git indexes, with exact tree comparison.\n"
                "The repository's real index and HEAD were unchanged. External theme sources are identical between deliveries.\n"
                "The separate new source package supplies the full checkpoint-based patch and complete source/evidence archives.\n"
                "The delta verifier does not re-read those archives; their own published receipts record archive readback.\n",
                encoding="utf-8")
            (staging / "SHA256SUMS").write_text(
                "".join(f"{file_hash(path)}  {path.name}\n" for path in sorted(staging.iterdir())), encoding="ascii")
        # Recheck after receipt generation, immediately before atomic publication.
        require((real_index.exists(), file_hash(real_index) if real_index.exists() else None) == index_before,
                "Real repository index changed before publication")
        require(git(repo, ["rev-parse", "--verify", "HEAD"], environment) == head_before,
                "Repository HEAD changed before publication")
        for path, before in inputs.items():
            require(signature(path) == before, f"A package input changed before publication: {path}")
        publish_no_replace(staging, output)
        published = True
        print(f"Published verified prior-delivery deltas: {output}")
    finally:
        if not published:
            shutil.rmtree(staging)


if __name__ == "__main__":
    try:
        main()
    except (OSError, ValueError, KeyError, subprocess.SubprocessError) as error:
        print(f"ERROR: {error}", file=sys.stderr)
        raise SystemExit(1)
